import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, postJson, putJson } from '../../api/http';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import { useCurrentUser } from '../session/SignIn';
import { useSheetToday } from '../sheet/SheetToday';

// A person's claims, listed under their row newest first. One form per row adds a claim, or edits
// the claim whose editor is open (URL state `editClaim`, the claim's id). Amounts come from the
// server as strings with two decimals and are added up in whole cents, never as floats.
export type Claim = { id: number; personId: number; amount: string; date: string; note: string };

type ClaimBody = { amount: string; date: string; note: string };

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'];
const sheetPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}`;

export function useClaims(sheet: string): Claim[] {
  return (
    useQuery({
      queryKey: claimsKey(sheet),
      queryFn: () => getJson<Claim[]>(`${sheetPath(sheet)}/claims`),
      enabled: !!sheet,
    }).data ?? []
  );
}

const toCents = (amount: string) => {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
};

/** The claims' amounts added up, with two decimals. */
export function claimed(claims: Claim[]): string {
  const cents = claims.reduce((sum, c) => sum + toCents(c.amount), 0);
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

export function ClaimedTotal({ sheet }: { sheet: string }) {
  const claims = useClaims(sheet);
  return (
    <p>
      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims)}</strong>
    </p>
  );
}

/** The claims cell of a person's row: the claim form and the person's claims, newest first. */
export function PersonClaims({ sheet, personId, claims }: { sheet: string; personId: number; claims: Claim[] }) {
  const [editId, setEditId] = useSearchParam('editClaim', asNumber);
  const editing = claims.find((c) => c.id === editId);

  return (
    <>
      {/* Keyed so opening another claim's editor (or closing it) refills the form. */}
      <ClaimForm key={editing ? `edit-${editing.id}` : 'add'} sheet={sheet} personId={personId}
        editing={editing} onDone={() => setEditId(undefined)} />
      <ul>
        {claims.map((c) => (
          <li key={c.id} data-testid={`claim-row-${c.id}`}>
            <span data-testid="claim-amount">{c.amount}</span>{' '}
            <span data-testid="claim-date">{c.date}</span>{' '}
            <span data-testid="claim-note">{c.note}</span>{' '}
            <button type="button" data-testid="claim-edit" onClick={() => setEditId(c.id)}>
              Edit
            </button>
          </li>
        ))}
      </ul>
    </>
  );
}

function ClaimForm({ sheet, personId, editing, onDone }: {
  sheet: string; personId: number; editing?: Claim; onDone: () => void;
}) {
  const queryClient = useQueryClient();
  const today = useSheetToday(sheet);
  const [amount, setAmount] = useState(editing?.amount ?? '');
  // Undefined until changed: the sheet's today, which the server fills in when the date is blank.
  const [date, setDate] = useState<string | undefined>(editing?.date);
  const [note, setNote] = useState(editing?.note ?? '');
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const save = useMutation({
    mutationFn: (body: ClaimBody) =>
      editing
        ? putJson<Claim>(`${sheetPath(sheet)}/claims/${editing.id}${by}`, body)
        : postJson<Claim>(`${sheetPath(sheet)}/people/${personId}/claims${by}`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      if (editing) {
        onDone();
      } else {
        setAmount('');
        setDate(undefined);
        setNote('');
      }
    },
  });
  const changed = <T,>(set: (v: T) => void) => (v: T) => {
    save.reset();
    set(v);
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        save.reset();
        // A missing, negative or over-precise amount is refused by the server (400).
        save.mutate({ amount, date: date ?? '', note });
      }}
    >
      <input data-testid="claim-form-amount" placeholder="Amount" inputMode="decimal" value={amount}
        onChange={(e) => changed(setAmount)(e.target.value)} />{' '}
      <input type="date" data-testid="claim-form-date" value={date ?? today ?? ''}
        onChange={(e) => changed(setDate)(e.target.value)} />{' '}
      <input data-testid="claim-form-note" placeholder="Note" value={note}
        onChange={(e) => changed(setNote)(e.target.value)} />{' '}
      <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
        {editing ? 'Save claim' : 'Add claim'}
      </button>
      {editing && (
        <button type="button" onClick={onDone}>
          Cancel
        </button>
      )}
      {save.isError && (
        <span role="alert" data-testid="claim-form-error">
          {' '}
          {(save.error instanceof HttpError && save.error.status === 400 && save.error.reason)
            || 'The claim could not be saved.'}
        </span>
      )}
    </form>
  );
}
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError, getJson, postJson, putJson } from '../../api/http';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import { useCurrentUser } from '../session/SignIn';
import { ClaimedTotal, PersonClaims, claimed, useClaims } from '../claims/Claims';

// The people on the sheet, in the order they were added. One form adds a person, or edits the
// person whose editor is open (URL state `editPerson`, the person's id).
export type Person = { id: number; name: string; grade: string };

const GRADES = ['A', 'B', 'C'];

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'];
const peoplePath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;

export function usePeople(sheet: string): Person[] {
  return (
    useQuery({
      queryKey: peopleKey(sheet),
      queryFn: () => getJson<Person[]>(peoplePath(sheet)),
      enabled: !!sheet,
    }).data ?? []
  );
}

function useEditPerson() {
  return useSearchParam('editPerson', asNumber);
}

export function People({ sheet }: { sheet: string }) {
  const people = usePeople(sheet);
  const [editId, setEditId] = useEditPerson();
  const editing = people.find((p) => p.id === editId);
  const claims = useClaims(sheet);

  return (
    <section>
      <h2>People</h2>
      {/* Keyed so opening another person's editor (or closing it) refills the form. */}
      <PersonForm key={editing ? `edit-${editing.id}` : 'add'} sheet={sheet} editing={editing}
        onDone={() => setEditId(undefined)} />
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Claimed</th>
            <th>Claims</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {people.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <td data-testid="person-claimed">{claimed(claims.filter((c) => c.personId === p.id))}</td>
              <td>
                <PersonClaims sheet={sheet} personId={p.id} claims={claims.filter((c) => c.personId === p.id)} />
              </td>
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditId(p.id)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <ClaimedTotal sheet={sheet} />
    </section>
  );
}

function PersonForm({ sheet, editing, onDone }: { sheet: string; editing?: Person; onDone: () => void }) {
  const queryClient = useQueryClient();
  const [name, setName] = useState(editing?.name ?? '');
  const [grade, setGrade] = useState(editing?.grade ?? 'A');
  const [user] = useCurrentUser();
  const by = `?user=${encodeURIComponent(user ?? '')}`;
  const save = useMutation({
    mutationFn: (body: { name: string; grade: string }) =>
      editing
        ? putJson<Person>(`${peoplePath(sheet)}/${editing.id}${by}`, body)
        : postJson<Person>(`${peoplePath(sheet)}${by}`, body),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
      if (editing) {
        onDone();
      } else {
        setName('');
        setGrade('A');
      }
    },
  });

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        save.reset();
        // A blank or already-used name is refused by the server (400), which shows the form's error.
        save.mutate({ name, grade });
      }}
    >
      <label>
        Name{' '}
        <input
          data-testid="person-form-name"
          value={name}
          onChange={(e) => {
            save.reset();
            setName(e.target.value);
          }}
        />
      </label>{' '}
      <label>
        Grade{' '}
        <select
          data-testid="person-form-grade"
          value={grade}
          onChange={(e) => {
            save.reset();
            setGrade(e.target.value);
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {editing ? 'Save' : 'Add'}
      </button>
      {editing && (
        <button type="button" onClick={onDone}>
          Cancel
        </button>
      )}
      {save.isError && (
        <span role="alert" data-testid="person-form-error">
          {' '}
          {(save.error instanceof HttpError && save.error.status === 400 && save.error.reason)
            || 'The person could not be saved.'}
        </span>
      )}
    </form>
  );
}
import { createFileRoute } from '@tanstack/react-router';
import { SignIn, useCurrentUser } from '../features/session/SignIn';
import { SheetPicker, useSheetId } from '../features/session/SheetPicker';
import { SheetToday } from '../features/sheet/SheetToday';
import { People } from '../features/people/People';

// The one screen. Sign in by name, then load a sheet by id; everything else is per sheet.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useCurrentUser();
  const sheet = useSheetId();
  return (
    <>
      <SignIn />
      {user && <SheetPicker />}
      {user && sheet && <SheetToday sheet={sheet} />}
      {user && sheet && <People sheet={sheet} />}
      {user && !sheet && <p data-testid="home-empty">Nothing here yet.</p>}
    </>
