-- One row per sheet that has stored state of its own. A sheet without a row starts empty.
-- today: the sheet's "today" date; NULL means the real date.
CREATE TABLE sheet (
    id    VARCHAR(100) PRIMARY KEY,
    today DATE
);
-- The people on a sheet, listed in the order they were added (by id).
-- name: as entered, never blank; grade: one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL,
    name     VARCHAR(200) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person's name is unique on the sheet, compared without regard to case. Names are stored
-- without surrounding spaces; name_key is the name as compared.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A person's claims, listed newest first (by id, descending).
-- amount: 0.00 or more, two decimals; claim_date: defaults to the sheet's today; note: may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)  NOT NULL,
    person_id  BIGINT        NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE          NOT NULL,
    note       VARCHAR(1000) NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
# The audit line is written last, once every rule has passed, so a refused change writes none.
# Validate first so a blank name or unknown grade is a 400 and nothing is written; a name already
# in use on the sheet is also a 400.
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: check
check:
  class: net.officefloor.hq.app.person.CheckPersonName
  govern: [ transaction ]
  next: create
create:
  class: net.officefloor.hq.app.person.CreatePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.AuditPersonAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPersonCreated
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheetToday
  govern: [ readonly-transaction ]
# Validate first so an invalid date is a 400 and nothing is written.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetToday
  next: save
save:
  class: net.officefloor.hq.app.sheet.SaveSheetToday
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheetToday
  govern: [ transaction ]
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app.person;

import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        String name = request == null ? null : request.name();
        String grade = request == null ? null : request.grade();
        if (name == null || name.isBlank()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (grade == null || !GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        // Stored without surrounding spaces.
        body.set(new PersonRequest(name.strip(), grade));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
